import {en,ja} from './i18n.js';
import {localizeError} from './errors.js';
import {bookmarklet} from './source-link.js';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=localStorage.getItem('folio-language')||'en', config, draft=null, baseline='', librarySnapshot=null, currentWork=null, routeVersion=0, jobTimer=null, suggestionTimer;
let theme=localStorage.getItem('folio-theme')||'dark', searchDraft='';
document.documentElement.dataset.theme=theme;
document.querySelector('meta[name="theme-color"]').content=theme==='light'?'#f6f5f1':'#101010';
const displayName=e=>e.display_name||e.display_alias||e.name;
const metadataQuery=(e,kind=e.kind)=>(kind==='tag'?(e.gender||'neutral'):kind)+':'+JSON.stringify(e.name);
const metadataHref=(e,kind)=>'#/library?'+new URLSearchParams({q:metadataQuery(e,kind)});
const t=k=>(lang==='ja'?ja:en)[k]??en[k]??k;
const symbols={Star:['★','☆'],Heart:['♥','♡'],Circle:['●','○'],Diamond:['◆','◇'],Square:['■','□'],Triangle:['▲','△'],Flower:['✿','❀'],Sun:['☀','☀'],Moon:['☾','☾'],Sparkle:['✦','✧']};
const paths={book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4z"/><path d="M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',tag:'<path d="m3 3 9 0 9 9-9 9-9-9z"/><circle cx="7.5" cy="7.5" r="1"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 2 3-1 3 4 3-2 1-3 4-1-1-4-3-1-1-4z"/>',arrow:'<path d="M20 12H4m6-6-6 6 6 6"/>',external:'<path d="M14 3h7v7m0-7-11 11M10 3H3v18h18v-7"/>',dice:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="7.5" cy="7.5" r=".5"/><circle cx="16.5" cy="7.5" r=".5"/><circle cx="12" cy="12" r=".5"/><circle cx="7.5" cy="16.5" r=".5"/><circle cx="16.5" cy="16.5" r=".5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',edit:'<path d="m4 16-1 5 5-1L21 7l-4-4zM14 6l4 4"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;
const btn=(text,id,style='',ico='')=>`<button type="button" class="btn ${style}" ${id?`id="${id}"`:''}>${ico?icon(ico):''}${esc(text)}</button>`;
function toast(message){const el=$('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500)}
async function api(path,method='GET',body){const res=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json',...(config?{'X-Library-Token':config.token}:{})},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(localizeError(data.error||t('error'),lang));return data}
function error(el,e){el.innerHTML=`<div class="error" role="alert">${esc(localizeError(e.message||e,lang))}</div>`}
function nav(path){location.hash=path}
async function refreshConfig(){config=await api('config')}
function route(){const [path,qs='']=(location.hash.slice(1)||'/library').split('?');return {path,params:new URLSearchParams(qs)}}
function shell(active,content,bottom=true){
 document.documentElement.lang=lang;document.documentElement.dataset.theme=theme;
 const navs=[['library','grid','/library'],['metadata','tag','/metadata'],['ratings','star','/ratings'],['imports','upload','/imports'],['settings','settings','/settings']];
 $('#app').innerHTML=`<div class="shell"><div class="mobile-head"><a class="brand" href="#/library"><span class="brandmark">f</span>Folio<span class="muted small"> / ${esc(t('library'))}</span></a><button class="iconbtn" id="menu" aria-label="${esc(t('settings'))}">${icon('menu')}</button></div><aside class="sidebar"><a class="brand" href="#/library"><span class="brandmark">f</span>Folio</a><div class="nav-caption">${esc(t('localLabel'))}</div>${navs.map(([key,ico,path])=>`<a class="navitem ${active===key?'active':''}" href="#${path}">${icon(ico)}${esc(t(key))}</a>`).join('')}<div class="sidebar-bottom"><div class="locale"><button data-lang="en" class="${lang==='en'?'chosen':''}">EN</button><button data-lang="ja" class="${lang==='ja'?'chosen':''}">日本語</button></div><div class="local"><span class="dot"></span>${esc(t('localLabel'))}<br>${esc(t('localHint'))}</div></div></aside><main class="main">${content}</main>${bottom?`<nav class="bottom-bar utility-bar" aria-label="${esc(t('library'))}"><form id="bottom-search-form" class="utility-search search-wrap" role="search"><input id="query" aria-label="${esc(t('search'))}" placeholder="${esc(t('searchPlaceholder'))}" value="${esc(searchDraft)}" autocomplete="off"><button id="bottom-search" type="submit" aria-label="${esc(t('search'))}" title="${esc(t('search'))}">${icon('search')}</button><div id="suggestions"></div></form><button id="bottom-random" type="button" aria-label="${esc(t('random'))}" title="${esc(t('random'))}">${icon('dice')}</button><button id="bottom-add" type="button" aria-label="${esc(t('add'))}" title="${esc(t('add'))}">${icon('plus')}</button></nav>`:''}</div>`;
 updateUtilityFocus();
 $('#menu')?.addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
 $$('.navitem').forEach(a=>a.addEventListener('click',()=>$('.sidebar').classList.remove('open')));
 $$('[data-lang]').forEach(b=>b.onclick=()=>switchLanguage(b.dataset.lang));
 $('#bottom-add')?.addEventListener('click',()=>{captureLibrary();nav('/new')});
 $('#bottom-search-form')?.addEventListener('submit',e=>{e.preventDefault();submitSearch()});
 if($('#query')){$('#query').oninput=()=>{searchDraft=$('#query').value;suggest($('#query'))};$('#query').onkeydown=e=>{if(e.key==='Escape')$('#suggestions').innerHTML=''}}
 $('#bottom-random')?.addEventListener('click',async()=>{try{const q=route().path==='/library'?(route().params.get('q')||''):'';const result=await api('works?random=1&q='+encodeURIComponent(q));if(!result.items.length)return toast(t('noResults'));captureLibrary();nav('/work/'+result.items[0].id)}catch(e){toast(e.message)}});
}
function switchLanguage(next){lang=next;localStorage.setItem('folio-language',lang);render(true)}
function heading(title,sub,action='',eyebrow=''){return `<div class="pagehead"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action}</div>`}
function placeholder(unavailable=false,hitomi=false){return `<div class="placeholder" ${unavailable?`title="${esc(t(hitomi?'hitomiCoverHint':'externalCoverHint'))}"`:''}>${icon('book')}<span>${esc(t(unavailable?'coverUnavailable':'noCover'))}</span>${hitomi?`<small>${esc(t('viewCoverOnSource'))}</small>`:''}</div>`}
function image(w,extra=''){const relay=w.id&&/^https?:\/\/(?:[ab]?tn)\.(?:hitomi\.la|gold-usergeneratedcontent\.net)\//.test(w.cover);const src=relay?'/api/works/'+encodeURIComponent(w.id)+'/cover':w.cover;return `<div class="cover ${extra}">${w.cover?`<img src="${esc(src)}" alt="${esc(w.title)}" loading="lazy" referrerpolicy="no-referrer" ${relay?'data-relay="hitomi"':''}>`:placeholder()}${w.category?`<span class="cover-badge">${esc(t(w.category))}</span>`:''}</div>`}
function images(){$$('.cover img').forEach(img=>{const failed=()=>{if(img.isConnected)img.outerHTML=placeholder(true,img.dataset.relay==='hitomi')};img.onerror=failed;if(img.complete&&!img.naturalWidth)failed()})}
function ratingDisplay(w,d){const n=w.ratings?.[d.id];const [on,off]=symbols[d.symbol]||symbols.Star;return `<div class="ratingline"><span>${d.number}. ${esc(d.name)}</span>${n?`<span class="symbols">${esc(on.repeat(n))}<span class="off">${esc(off.repeat(d.maximum-n))}</span></span><small>${n}/${d.maximum}</small>`:`<small>${esc(t('unrated'))}</small>`}</div>`}
function card(w){return `<a class="card" href="#/work/${w.id}">${image(w)}<div class="card-title">${esc(w.title)}</div><div class="card-author">${esc(w.author.map(a=>displayName(a)).join(', ')||t('notSpecified'))}</div><div class="card-tags">${w.tag.slice(0,3).map(a=>`<span class="tag ${a.gender}">${esc(displayName(a))}</span>`).join('')}${w.tag.length>3?`<span class="tag">+${w.tag.length-3}</span>`:''}</div>${config.dimensions.filter(d=>d.gallery).map(d=>ratingDisplay(w,d)).join('')}</a>`}
let libraryItems=[],total=0,seed=String(Date.now()),activeLibraryHash='',querySequence=0;
function markLibraryDirty(){if(librarySnapshot)librarySnapshot.dirty=true}
function captureLibrary(){if(route().path==='/library')librarySnapshot={hash:location.hash.slice(1)||'/library',items:libraryItems,total,seed,scroll:scrollY}}
async function library(){
 const {params}=route();const q=params.get('q')||'',sort=validLibrarySort(params.get('sort')||localStorage.getItem('folio-library-sort')||'newest');
 localStorage.setItem('folio-library-sort',sort);params.set('sort',sort);
 const canonical='/library?'+params;history.replaceState(null,'','#'+canonical);previousHash=location.hash;
 searchDraft=q;activeLibraryHash=canonical;
 shell('library',heading(t('libraryTitle'),t('librarySubtitle'),`<div class="desktop-add">${btn(t('add'),'add-top','primary','plus')}</div>`,t('collection'))+`<div class="toolbar library-toolbar"><span class="tag active-query">${esc(q||t('library'))}</span><select id="sort" aria-label="${esc(t('newest'))}">${['newest','oldest','recent','least','random'].map(k=>`<option value="${k}" ${sort===k?'selected':''}>${esc(t(k==='random'?'randomSort':k))}</option>`).join('')}${config.dimensions.map(d=>`<option value="rating${d.number}" ${sort==='rating'+d.number?'selected':''}>${esc(t('highest'))}: ${d.number}. ${esc(d.name)}</option>`).join('')}</select></div><div class="search-help">${esc(t('help'))} &nbsp; <code>${esc(t('searchExample'))}</code></div><div id="library-errors"></div><div class="results-line"><span id="count">${esc(t('loading'))}</span>${sort==='random'?`<button id="reshuffle" class="iconbtn" aria-label="${esc(t('reshuffle'))}">${icon('refresh')}</button>`:''}</div><div id="gallery" class="gallery"></div><div id="library-empty"></div><div id="more"></div>`);
 $('#add-top').onclick=()=>{captureLibrary();nav('/new')};
 $('#sort').onchange=updateLibraryQuery;
 $('#reshuffle')?.addEventListener('click',()=>{seed=String(Date.now());fetchLibrary(false)});
 if(librarySnapshot?.hash===activeLibraryHash){libraryItems=librarySnapshot.items;total=librarySnapshot.total;seed=librarySnapshot.seed;if(librarySnapshot.dirty){const target=Math.max(40,libraryItems.length),savedScroll=librarySnapshot.scroll;libraryItems=[];const p=route().params;while(libraryItems.length<target){const r=await api(`works?q=${encodeURIComponent(p.get('q')||'')}&sort=${p.get('sort')||'newest'}&seed=${seed}&offset=${libraryItems.length}`);total=r.total;libraryItems.push(...r.items);if(!r.items.length||libraryItems.length>=total)break}librarySnapshot.dirty=false;paintLibrary();requestAnimationFrame(()=>scrollTo(0,savedScroll))}else{paintLibrary();requestAnimationFrame(()=>scrollTo(0,librarySnapshot.scroll))}}
 else {libraryItems=[];await fetchLibrary(false)}
}
function submitSearch(){$('#query')?.blur();searchDraft=$('#query')?.value||'';const sort=validLibrarySort($('#sort')?.value||localStorage.getItem('folio-library-sort')||'newest');const p=new URLSearchParams();if(searchDraft.trim())p.set('q',searchDraft.trim());p.set('sort',sort);const target='/library'+(p.size?'?'+p:'');$('#suggestions')&&( $('#suggestions').innerHTML='');if(route().path==='/library'){librarySnapshot=null;seed=String(Date.now());if((location.hash.slice(1)||'/library')===target){fetchLibrary(false);return}}nav(target)}
function validLibrarySort(value){return ['newest','oldest','recent','least','random',...config.dimensions.map(d=>'rating'+d.number)].includes(value)?value:'newest'}
function updateLibraryQuery(){const q=route().params.get('q')||'',sort=validLibrarySort($('#sort')?.value||'newest');localStorage.setItem('folio-library-sort',sort);const p=new URLSearchParams();if(q)p.set('q',q);p.set('sort',sort);const hash='/library?'+p;history.replaceState(null,'','#'+hash);previousHash=location.hash;activeLibraryHash=hash;seed=String(Date.now());librarySnapshot=null;fetchLibrary(false)}
async function fetchLibrary(append){const seq=++querySequence;const q=route().params.get('q')||'',sort=$('#sort')?.value||'newest';try{const result=await api(`works?q=${encodeURIComponent(q)}&sort=${sort}&seed=${seed}&offset=${append?libraryItems.length:0}`);if(seq!==querySequence||route().path!='/library')return;$('#library-errors').innerHTML='';libraryItems=append?[...libraryItems,...result.items]:result.items;total=result.total;paintLibrary()}catch(e){if($('#library-errors'))error($('#library-errors'),e)}}
function paintLibrary(){if(!$('#gallery'))return;$('#count').textContent=`${total.toLocaleString()} ${t('works')} · ${libraryItems.length} ${t('showing')}`;$('#gallery').innerHTML=libraryItems.map(card).join('');images();$$('.card').forEach(a=>a.onclick=captureLibrary);$('#library-empty').innerHTML=total?'':`<div class="empty"><div class="empty-icon">${icon(route().params.get('q')?'search':'book')}</div><h2>${esc(t(route().params.get('q')?'noResults':'emptyTitle'))}</h2><p>${esc(t(route().params.get('q')?'noResultsText':'emptyText'))}</p><div class="row">${route().params.get('q')?btn(t('clear'),'empty-clear'):btn(t('add'),'empty-add','primary','plus')+`<a class="btn" href="#/imports">${icon('upload')}${esc(t('imports'))}</a>`}</div></div>`;$('#empty-add')?.addEventListener('click',()=>nav('/new'));$('#empty-clear')?.addEventListener('click',()=>{$('#query').value='';searchDraft='';submitSearch()});$('#more').innerHTML=libraryItems.length<total?btn(t('loadMore'),'load-more','loadmore'):'';$('#load-more')?.addEventListener('click',()=>fetchLibrary(true))}
function fragment(text){let quoted=false,escaped=false,start=0;for(let i=0;i<text.length;i++){const ch=text[i];if(escaped){escaped=false;continue}if(quoted&&ch==='\\'){escaped=true;continue}if(ch==='"')quoted=!quoted;else if(!quoted&&(ch==='/'||/\s/.test(ch)))start=i+1}const raw=text.slice(start),neg=raw.startsWith('-');const term=neg?raw.slice(1):raw;const sep=term.indexOf(':');return {start,neg,field:sep>=0?term.slice(0,sep):'',value:(sep>=0?term.slice(sep+1):term).replace(/^"/,'').replace(/"$/,'')}}
let suggestionVersion=0;
async function suggest(input){clearTimeout(suggestionTimer);const seq=++suggestionVersion;const container=$('#suggestions');if(!container)return;container.innerHTML='';const f=fragment(input.value);if(!f.value)return;suggestionTimer=setTimeout(async()=>{try{const items=await api(`suggestions?q=${encodeURIComponent(f.value)}&field=${f.field}`);if(seq!==suggestionVersion||!container.isConnected||!items.length)return;container.innerHTML=`<div class="suggestions">${items.map((i,n)=>`<button type="button" data-index="${n}"><span>${esc(i.field)}:${esc(i.label)}</span><small>${esc(i.detail)}</small></button>`).join('')}</div>`;const select=n=>{const i=items[n];const val=/\s|[\/"\\]/.test(i.value)?JSON.stringify(i.value):i.value;input.value=input.value.slice(0,f.start)+(f.neg?'-':'')+i.field+':'+val+' ';container.innerHTML='';searchDraft=input.value;input.focus()};$$('button',container).forEach(b=>b.onclick=()=>select(Number(b.dataset.index)));input.onkeydown=e=>{if(e.isComposing){if(e.key==='Enter')e.preventDefault();return}const buttons=$$('button',container);let idx=buttons.findIndex(b=>b.classList.contains('selected'));if((e.key==='ArrowDown'||e.key==='ArrowUp')&&buttons.length){e.preventDefault();idx=(idx+(e.key==='ArrowDown'?1:buttons.length-1)+buttons.length)%buttons.length;buttons.forEach((b,n)=>b.classList.toggle('selected',n===idx))}else if(e.key==='Enter'){e.preventDefault();if(idx>=0)select(idx);else{container.innerHTML='';submitSearch()}}else if(e.key==='Escape')container.innerHTML=''}}catch{container.innerHTML=''}},180)}
async function detail(id){const w=await api('works/'+id+'/open','POST',{});currentWork=w;const source=w.links.find(l=>l.is_primary);shell('library',`<div class="row between"><a class="btn ghost" href="#${esc(librarySnapshot?.hash||'/library')}">${icon('arrow')}${esc(t('back'))}</a>${btn(t('edit'),'edit-work','','edit')}</div><div class="detail"><div class="detail-cover">${source?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${image(w)}</a>`:image(w)}</div><div><div class="eyebrow">${esc(w.category?t(w.category):t('library'))}</div><h1>${esc(w.title)}</h1><div class="ratings">${config.dimensions.map(d=>ratingDisplay(w,d)).join('')}</div><div class="row wrap"><span class="tag">${esc(w.language||t('notSpecified'))}</span>${w.pages!=null?`<span class="tag">${esc(t('pages'))}: ${w.pages}</span>`:''}${w.bought?`<span class="tag">${esc(t('bought'))}</span>`:''}${source?`<a class="btn primary" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(t('openSource'))}</a>`:''}</div><div class="meta">${['author','circle','tag','series','character'].filter(k=>k==='author'||k==='circle'||w[k].length).map(k=>`<div><label>${esc(t(k))}</label>${w[k].length?`<div class="row wrap">${w[k].map(e=>`<a class="tag ${e.gender}" href="${esc(metadataHref(e,k))}">${esc(displayName(e))}</a>`).join('')}</div>`:`<span class="muted small">${esc(t('notSpecified'))}</span>`}</div>`).join('')}${w.review?`<div><label>${esc(t('review'))}</label><p class="review">${esc(w.review)}</p></div>`:''}${w.links.length?`<div><label>${esc(t('sources'))}</label><div class="source-list">${w.links.map(l=>`<a class="source-link" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}<span>${esc(l.label||l.url)}</span>${l.is_primary?`<span class="tag">${esc(t('primary'))}</span>`:''}</a>`).join('')}</div></div>`:''}</div></div></div>`);images();$('#edit-work').onclick=()=>nav('/edit/'+id)}

const dialog=$('#dialog');
function modal(html){dialog.innerHTML=html;dialog.showModal()}
function closeModal(){dialog.close();dialog.innerHTML=''}
async function confirm(title,text,action=t('delete')){return new Promise(resolve=>{modal(`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="actions">${btn(t('cancel'),'confirm-no')}${btn(action,'confirm-yes','primary')}</div>`);$('#confirm-no').onclick=()=>{closeModal();resolve(false)};$('#confirm-yes').onclick=()=>{closeModal();resolve(true)};dialog.oncancel=()=>resolve(false)})}
const field=(key,value='',type='text',extra='')=>`<label><span>${esc(t(key))}</span><input data-field="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function blank(){return {title:'',cover:'',category:'',language:'',pages:null,review:'',bought:false,author:[],circle:[],tag:[],series:[],character:[],links:[],ratings:{}}}
function scoreEditor(d){const n=draft.ratings[d.id]||0;return `<div><span class="field-title">${d.number}. ${esc(d.name)} <small>(${d.maximum})</small></span><div class="score-editor">${Array.from({length:d.maximum},(_,i)=>`<button type="button" data-score="${d.id}:${i+1}" class="${i<n?'on':''}" aria-label="${esc(d.name)} ${i+1}/${d.maximum}">${symbols[d.symbol][i<n?0:1]}</button>`).join('')}<button type="button" class="clear-score" data-score="${d.id}:0">${esc(t('clearRating'))}</button><small>${n?`${n}/${d.maximum}`:esc(t('unrated'))}</small></div></div>`}
async function edit(id,reuse=false){if(!reuse||!draft){draft=id?await api('works/'+id):blank();baseline=JSON.stringify(draft)}shell('library',`<div class="row between"><button id="cancel-edit" class="btn ghost">${icon('arrow')}${esc(t('cancel'))}</button><span class="muted small">${esc(t('entryHint'))}</span></div><div class="entry-form"><div class="pagehead"><div><h1>${esc(t(id?'editWork':'newWork'))}</h1></div></div><div id="form-error"></div><form id="entry-form" class="stack"><section class="panel form-grid">${field('title',draft.title,'text','required class="title-input"')}<label><span>${esc(t('category'))}</span><select data-field="category"><option value="">${esc(t('notSpecified'))}</option>${Object.keys(config.categories).map(k=>`<option value="${k}" ${draft.category===k?'selected':''}>${esc(t(k))}</option>`).join('')}</select></label><div class="full">${field('cover',draft.cover,'url')}</div>${['author','circle','tag','series','character'].map(k=>`<div class="${k==='tag'?'full':''}"><div class="metadata-field-heading"><span class="field-title">${esc(t(k))}</span><button type="button" class="btn ghost clear-metadata" data-clear-kind="${k}" aria-label="${esc(t('clearMetadata')+' · '+t(k))}" ${draft[k].length?'':'disabled'}>${esc(t('clearMetadata'))}</button></div><div class="chips">${draft[k].map((e,i)=>`<span class="chip"><button type="button" data-edit-chip="${k}:${i}">${esc(displayName(e))}${k==='tag'?` · ${esc(t(e.gender))}`:''}</button><button type="button" data-remove-chip="${k}:${i}" aria-label="${esc(t('remove'))}">×</button></span>`).join('')}<button type="button" class="add-chip" data-add-kind="${k}">+ ${esc(t('select'))} / +</button></div></div>`).join('')}${field('language',draft.language)}${field('pages',draft.pages??'','number','min="0" step="1"')}</section><section class="panel"><h3>${esc(t('sources'))}</h3><p class="muted small">${esc(t('importHint'))}</p><div id="link-fields">${draft.links.map((l,i)=>`<div class="link-edit"><input type="radio" name="primary" aria-label="${esc(t('primary'))}" data-primary="${i}" ${l.is_primary?'checked':''}><div class="link-fields"><input type="url" data-link="${i}:url" value="${esc(l.url)}" placeholder="https://…" aria-label="${esc(t('workLink'))}"><input data-link="${i}:label" value="${esc(l.label)}" placeholder="${esc(t('sourceLabel'))}" aria-label="${esc(t('sourceLabel'))}"></div><button type="button" class="iconbtn" data-remove-link="${i}" aria-label="${esc(t('remove'))}">${icon('x')}</button></div>`).join('')}</div><div class="row wrap">${btn(t('addLink'),'add-link','','plus')}${btn(t('importMetadata'),'import-metadata','','upload')}</div></section><section class="panel stack"><h3>${esc(t('personal'))}</h3>${config.dimensions.length?config.dimensions.map(scoreEditor).join(''):`<p class="muted small">${esc(t('noRatings'))}</p>`}<label class="check-label"><input type="checkbox" data-field="bought" ${draft.bought?'checked':''}>${esc(t('bought'))}</label><label><span>${esc(t('review'))}</span><textarea data-field="review">${esc(draft.review)}</textarea></label></section></form></div><div class="bottom-bar edit-actions">${btn(t('save'),'save-work','primary')}${id?btn(t('delete'),'delete-work','danger'):''}</div>`);
 $$('[data-field]').forEach(el=>el.oninput=()=>{const k=el.dataset.field;draft[k]=k==='bought'?el.checked:k==='pages'?(el.value===''?null:Number(el.value)):el.value});
 $$('[data-link]').forEach(el=>el.oninput=()=>{const [i,k]=el.dataset.link.split(':');draft.links[i][k]=el.value});
 $$('[data-primary]').forEach(el=>el.onchange=()=>draft.links.forEach((l,i)=>l.is_primary=i===Number(el.dataset.primary)));
 $$('[data-remove-link]').forEach(b=>b.onclick=()=>{draft.links.splice(Number(b.dataset.removeLink),1);if(draft.links.length&&!draft.links.some(l=>l.is_primary))draft.links[0].is_primary=true;edit(id,true)});
 $('#add-link').onclick=()=>{draft.links.push({url:'',label:'',is_primary:!draft.links.length});edit(id,true)};
 $$('[data-remove-chip]').forEach(b=>b.onclick=()=>{const [k,i]=b.dataset.removeChip.split(':');draft[k].splice(Number(i),1);edit(id,true)});
 $$('[data-clear-kind]').forEach(b=>b.onclick=async()=>{const k=b.dataset.clearKind,editing=draft,scroll=window.scrollY;if(!editing[k].length||!await confirm(t('clearMetadataTitle').replace('{kind}',t(k)),t('clearMetadataText'),t('clearMetadata'))||draft!==editing)return;draft[k]=[];await edit(id,true);window.scrollTo(0,scroll)});
 $$('[data-add-kind]').forEach(b=>b.onclick=()=>chooseMetadata(b.dataset.addKind,item=>{if(!draft[b.dataset.addKind].some(e=>e.id===item.id))draft[b.dataset.addKind].push(item);edit(id,true)}));
 $$('[data-edit-chip]').forEach(b=>b.onclick=()=>{const [k,i]=b.dataset.editChip.split(':');metadataEditor(draft[k][i],k,async eid=>{draft[k][i]=await api('entities/'+eid);markLibraryDirty();edit(id,true)})});
 $$('[data-score]').forEach(b=>b.onclick=()=>{const [did,v]=b.dataset.score.split(':');if(Number(v))draft.ratings[did]=Number(v);else delete draft.ratings[did];edit(id,true)});
 $('#cancel-edit').onclick=async()=>{if(JSON.stringify(draft)!==baseline&&!await confirm(t('discardTitle'),t('discardText'),t('discard')))return;draft=null;nav(id?'/work/'+id:librarySnapshot?.hash||'/library')};
 $('#entry-form').onsubmit=e=>{e.preventDefault();saveDraft(id)};
 $('#save-work').onclick=()=>saveDraft(id);
 $('#delete-work')?.addEventListener('click',async()=>{if(!await confirm(t('deleteTitle'),t('deleteText')))return;await api('works/'+id,'DELETE');draft=null;markLibraryDirty();toast(t('deleted'));nav(librarySnapshot?.hash||'/library')});
 $('#import-metadata').onclick=()=>interactiveImport(id);
}
async function saveDraft(id){const b=$('#save-work');b.disabled=true;try{if(!$('#entry-form').reportValidity())return;const result=await api('works'+(id?'/'+id:''),id?'PUT':'POST',draft);draft=null;markLibraryDirty();if(result.warnings.length)toast(t('duplicateSource')+' '+result.warnings.join(', '));else toast(t('saved'));nav('/work/'+result.id)}catch(e){error($('#form-error'),e);$('#form-error').scrollIntoView({block:'center'})}finally{if(b.isConnected)b.disabled=false}}
async function chooseMetadata(kind,onSelect){modal(`<h2>${esc(t('choose'))}: ${esc(t(kind))}</h2><div class="stack"><input id="choose-query" placeholder="${esc(t('searchMetadata'))}"><div id="choose-list" class="directory-list"></div></div><div class="actions">${btn(t('close'),'choose-close')}${btn(t('createNew'),'choose-new','primary','plus')}</div>`);let sequence=0,timer;const paint=async q=>{const seq=++sequence;const items=await api('entities?kind='+kind+'&q='+encodeURIComponent(q));if(seq!==sequence||!$('#choose-list'))return;$('#choose-list').innerHTML=items.map(e=>`<div class="directory-row"><div><b>${esc(displayName(e))}</b><div class="subtitle">${kind==='tag'?esc(t(e.gender)):esc(e.aliases.join(', '))}</div></div><button type="button" class="btn" data-choose="${e.id}">${esc(t('select'))}</button></div>`).join('')||`<p class="muted">${esc(t('noneMetadata'))}</p>`;$$('[data-choose]').forEach(b=>b.onclick=()=>{const item=items.find(e=>e.id===b.dataset.choose);closeModal();onSelect(item)})};await paint('');$('#choose-query').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>paint(e.target.value),180)};$('#choose-close').onclick=closeModal;$('#choose-new').onclick=()=>metadataEditor(null,kind,async eid=>{const entity=await api('entities/'+eid);onSelect(entity)})}
async function metadataEditor(item,kind,onSave){
 if(dialog.open)closeModal();
 modal(`<h2>${esc(t(item?'edit':'newMetadata'))}: ${esc(t(kind))}</h2><p>${esc(t('sharedWarning'))}</p><div id="metadata-error"></div><form id="metadata-form" class="stack"><label><span>${esc(t('canonicalName'))}</span><input id="metadata-name" required value="${esc(item?.name||'')}"></label>${kind==='tag'?`<label><span>${esc(t('gender'))}</span><select id="metadata-gender">${['neutral','female','male'].map(g=>`<option value="${g}" ${(item?.gender||'neutral')===g?'selected':''}>${esc(t(g))}</option>`).join('')}</select></label>`:''}<label><span>${esc(t('aliases'))}</span><textarea id="metadata-aliases">${esc(item?.aliases?.join('\n')||'')}</textarea></label><label><span>${esc(t('displayAlias'))}</span><select id="metadata-display"></select><small class="muted">${esc(t('displayAliasHint'))}</small></label><label><span>${esc(t('sortReading'))}</span><input id="metadata-reading" value="${esc(item?.sort_reading||'')}"><small class="muted">${esc(t('sortReadingHint'))}</small></label><div class="actions">${btn(t('cancel'),'metadata-cancel')}<button class="btn primary" type="submit">${esc(t('save'))}</button></div></form>`);
 let selected=item?.display_alias||'';
 const aliases=()=>[...new Set($('#metadata-aliases').value.split('\n').map(a=>a.trim()).filter(Boolean))];
 function options(){const names=aliases();if(!names.includes(selected))selected='';$('#metadata-display').innerHTML=`<option value="">${esc($('#metadata-name').value.trim()||t('canonicalName'))} (${esc(t('canonicalName'))})</option>`+names.map(a=>`<option value="${esc(a)}" ${a===selected?'selected':''}>${esc(a)}</option>`).join('')}
 options();$('#metadata-display').onchange=e=>selected=e.target.value;
 $('#metadata-name').oninput=options;$('#metadata-aliases').oninput=options;
 $('#metadata-cancel').onclick=closeModal;
 $('#metadata-form').onsubmit=async e=>{e.preventDefault();try{const result=await api('entities'+(item?.id?'/'+item.id:''),item?.id?'PUT':'POST',{kind,name:$('#metadata-name').value,gender:$('#metadata-gender')?.value||'neutral',aliases:aliases(),display_alias:$('#metadata-display').value,sort_reading:$('#metadata-reading').value});markLibraryDirty();closeModal();onSave(result.id)}catch(e){error($('#metadata-error'),e)}};
}
async function interactiveImport(id,sourceDraft=false){const valid=draft.links.filter(l=>l.url);if(!valid.length){toast(t('addLink'));return}let link=valid.find(l=>l.is_primary)||valid[0];if(valid.length>1){const choice=await new Promise(resolve=>{modal(`<h2>${esc(t('importMetadata'))}</h2><div class="stack">${valid.map((l,i)=>`<button class="btn" data-import-link="${i}">${esc(l.label||l.url)}</button>`).join('')}</div><div class="actions">${btn(t('cancel'),'import-link-cancel')}</div>`);$$('[data-import-link]').forEach(b=>b.onclick=()=>{closeModal();resolve(valid[Number(b.dataset.importLink)])});$('#import-link-cancel').onclick=()=>{closeModal();resolve(null)};dialog.oncancel=()=>resolve(null)});if(!choice)return;link=choice}
 const activeDraft=draft,importVersion=routeVersion;const b=$('#import-metadata');b.disabled=true;b.textContent=t('loading');try{const incoming=await api('import','POST',{url:link.url,exclude:id||'',allow_duplicate_title:sourceDraft});if(draft!==activeDraft||routeVersion!==importVersion)return;for(const ambiguity of incoming.ambiguities){const selected=await new Promise(resolve=>{modal(`<h2>${esc(t('selectAlias'))}</h2><p>${esc(ambiguity.name)}</p><div class="stack">${ambiguity.choices.map(c=>`<button class="btn" data-alias-id="${c.id}">${esc(displayName(c))} · ${esc(t(c.gender))}</button>`).join('')}</div>${btn(t('cancel'),'alias-cancel')}`);$$('[data-alias-id]').forEach(b=>b.onclick=()=>{closeModal();resolve(b.dataset.aliasId)});$('#alias-cancel').onclick=()=>{closeModal();resolve(null)};dialog.oncancel=()=>resolve(null)});if(!selected)return;incoming[ambiguity.kind].find(e=>e.name===ambiguity.name&&(e.gender||'neutral')===ambiguity.gender).id=selected}
 const singles=['title','cover','category','language','pages'];const conflicts=singles.filter(k=>draft[k]!==''&&draft[k]!=null&&incoming[k]!==''&&incoming[k]!=null&&draft[k]!==incoming[k]);let replacements=[];
 if(conflicts.length){replacements=await new Promise(resolve=>{modal(`<h2>${esc(t('replaceTitle'))}</h2><p>${esc(t('replaceText'))}</p><div class="stack">${conflicts.map(k=>`<label class="check-label"><input type="checkbox" data-replace="${k}"><span><b>${esc(t(k))}</b><br><small>${esc(draft[k])} → ${esc(incoming[k])}</small></span></label>`).join('')}</div><div class="actions">${btn(t('cancel'),'replacement-cancel')}${btn(t('apply'),'replacement-apply','primary')}</div>`);$('#replacement-cancel').onclick=()=>{closeModal();resolve(null)};$('#replacement-apply').onclick=()=>{const values=$$('[data-replace]:checked').map(b=>b.dataset.replace);closeModal();resolve(values)};dialog.oncancel=()=>resolve(null)});if(replacements===null)return}
 if(draft!==activeDraft||routeVersion!==importVersion)return;
 for(const k of singles)if(draft[k]===''||draft[k]==null||replacements.includes(k))if(incoming[k]!==''&&incoming[k]!=null)draft[k]=incoming[k];
 for(const k of ['author','circle','tag','series','character'])for(const e of incoming[k]||[])if(!draft[k].some(a=>(e.id&&a.id===e.id)||a.name===e.name&&(a.gender||'neutral')===(e.gender||'neutral')))draft[k].push(e);
 toast(t('importDone')+(incoming.warnings.length?' · '+incoming.warnings.map(w=>localizeError(w,lang)).join('; '):''));edit(id,true);
 }catch(e){if(draft===activeDraft&&routeVersion===importVersion)error($('#form-error'),e)}finally{if(b.isConnected){b.disabled=false;b.textContent=t('importMetadata')}}}

let metadataKind='tag',metadataSort='name_asc',metadataFilter='';
async function metadata(){
 clearTimeout(metadata.timer);
 shell('metadata',heading(t('metadataTitle'),t('metadataHint'),btn(t('newMetadata'),'metadata-add','primary','plus'))+`<div class="directory-tabs">${['tag','author','circle','series','character'].map(k=>`<button data-kind="${k}" class="${k===metadataKind?'active':''}">${esc(t(k))}</button>`).join('')}</div><div class="toolbar metadata-toolbar"><div class="searchbox search-wrap">${icon('search')}<input id="metadata-search" aria-label="${esc(t('searchMetadata'))}" placeholder="${esc(t('searchMetadata'))}" value="${esc(metadataFilter)}"></div><select id="metadata-sort" aria-label="${esc(t('sortMetadata'))}">${['name_asc','name_desc','uses_desc','uses_asc','newest','oldest'].map(k=>`<option value="${k}" ${k===metadataSort?'selected':''}>${esc(t('meta_'+k))}</option>`).join('')}</select></div><div id="metadata-error-page"></div><div class="results-line" id="metadata-count"></div><div id="directory" class="directory-list"></div><div id="metadata-more"></div>`);
 $$('[data-kind]').forEach(b=>b.onclick=()=>{metadataKind=b.dataset.kind;metadata()});
 $('#metadata-add').onclick=()=>metadataEditor(null,metadataKind,()=>metadata());
 const directory=$('#directory'),kind=metadataKind;let sequence=0,items=[],count=0;
 async function load(append=false){
  const seq=++sequence;
  try{
   const result=await api('entities?'+new URLSearchParams({kind,q:metadataFilter,sort:metadataSort,paged:1,limit:100,offset:append?items.length:0}));
   if(seq!==sequence||!directory.isConnected)return;
   items=append?[...items,...result.items]:result.items;count=result.total;
   $('#metadata-error-page').innerHTML='';$('#metadata-count').textContent=`${count.toLocaleString()} · ${items.length} ${t('showing')}`;
   directory.innerHTML=items.map(e=>`<div class="directory-row"><div class="directory-info"><div class="name"><a class="metadata-name-link" href="${esc(metadataHref(e,kind))}">${esc(displayName(e))}</a> ${kind==='tag'?`<span class="tag ${e.gender}">${esc(t(e.gender))}</span>`:''}</div><div class="subtitle">${e.uses} ${esc(t('uses'))}${e.display_alias?' · '+esc(e.name):''}${e.aliases.some(a=>a!==e.display_alias)?' · '+esc(e.aliases.filter(a=>a!==e.display_alias).join(', ')):''}</div></div><div class="row"><button type="button" class="btn" data-edit-meta="${e.id}">${esc(t('edit'))}</button><button class="iconbtn" data-delete-meta="${e.id}" aria-label="${esc(t('delete'))}">${icon('x')}</button></div></div>`).join('')||`<div class="empty"><h2>${esc(t('noneMetadata'))}</h2><p>${esc(t('emptyDirectory'))}</p></div>`;
   $$('[data-edit-meta]',directory).forEach(b=>b.onclick=()=>{const item=items.find(e=>e.id===b.dataset.editMeta);metadataEditor(item,kind,()=>metadata());const actions=$('.actions',dialog),mergeBtn=document.createElement('button');mergeBtn.type='button';mergeBtn.className='btn';mergeBtn.textContent=t('merge');actions.prepend(mergeBtn);mergeBtn.onclick=()=>mergeEditor(item,items)});
   $$('[data-delete-meta]',directory).forEach(b=>b.onclick=async()=>{const e=items.find(e=>e.id===b.dataset.deleteMeta);if(await confirm(t('deleteMetadata'),`${e.uses} ${t('uses')}. ${t('deleteMetadataText')}`)){try{await api('entities/'+e.id,'DELETE');markLibraryDirty();load()}catch(err){if(directory.isConnected)error($('#metadata-error-page'),err)}}});
   $('#metadata-more').innerHTML=items.length<count?btn(t('loadMore'),'metadata-load-more','loadmore'):'';
   $('#metadata-load-more')?.addEventListener('click',()=>load(true));
  }catch(e){if(seq===sequence&&directory.isConnected)error($('#metadata-error-page'),e)}
 }
 $('#metadata-search').oninput=e=>{metadataFilter=e.target.value;++sequence;clearTimeout(metadata.timer);metadata.timer=setTimeout(()=>load(),180)};
 $('#metadata-sort').onchange=e=>{metadataSort=e.target.value;load()};await load();
}
function mergeEditor(item,items){closeModal();modal(`<h2>${esc(t('merge'))}: ${esc(displayName(item))}</h2><p>${esc(t('mergeText'))}</p><div id="merge-error"></div><div class="stack"><input id="merge-query" placeholder="${esc(t('searchMetadata'))}"><label><span>${esc(t('mergeInto'))}</span><select id="merge-target"></select></label></div><div class="actions">${btn(t('cancel'),'merge-cancel')}${btn(t('merge'),'merge-confirm','primary')}</div>`);let sequence=0,timer;const load=async()=>{const seq=++sequence;const candidates=await api('entities?kind='+item.kind+'&q='+encodeURIComponent($('#merge-query').value));if(seq!==sequence||!$('#merge-target'))return;const targets=candidates.filter(e=>e.id!==item.id&&e.gender===item.gender);$('#merge-target').innerHTML=targets.map(e=>`<option value="${e.id}">${esc(displayName(e))}</option>`).join('');$('#merge-confirm').disabled=!targets.length};$('#merge-query').oninput=()=>{clearTimeout(timer);timer=setTimeout(load,180)};load();$('#merge-cancel').onclick=closeModal;$('#merge-confirm').onclick=async()=>{try{await api('entities/'+item.id+'/merge','POST',{target:$('#merge-target').value});closeModal();markLibraryDirty();metadata()}catch(e){error($('#merge-error'),e)}}}
async function ratingPage(){await refreshConfig();shell('ratings',heading(t('ratingsTitle'),t('ratingsHint'),btn(t('newDimension'),'dimension-add','primary','plus'))+`<div class="notice">${esc(t('dimensionWarning'))}</div><div class="directory-list" id="dimensions"></div>`);$('#dimensions').innerHTML=config.dimensions.map(d=>`<div class="directory-row"><div class="row"><div class="dimension-number">${d.number}</div><div><div class="name">${esc(d.name)}</div><div class="subtitle">rating${d.number} · 1–${d.maximum} · ${esc(t(d.symbol))}${d.gallery?' · '+esc(t('galleryVisible')):''}</div></div></div><div class="row"><button class="btn" data-edit-dimension="${d.id}">${esc(t('edit'))}</button><button class="iconbtn" data-delete-dimension="${d.id}" aria-label="${esc(t('delete'))}">${icon('x')}</button></div></div>`).join('')||`<div class="empty"><div class="empty-icon">${icon('star')}</div><h2>${esc(t('noRatings'))}</h2></div>`;$('#dimension-add').onclick=()=>dimensionEditor();$$('[data-edit-dimension]').forEach(b=>b.onclick=()=>dimensionEditor(config.dimensions.find(d=>d.id===b.dataset.editDimension)));$$('[data-delete-dimension]').forEach(b=>b.onclick=async()=>{if(await confirm(t('deleteDimension'),t('deleteDimensionText'))){await api('dimensions/'+b.dataset.deleteDimension,'DELETE');ratingPage()}})}
function dimensionEditor(d){
 modal(`<h2>${esc(t(d?'edit':'newDimension'))}${d?' · rating'+d.number:''}</h2><div id="dimension-error"></div><form id="dimension-form" class="stack"><label><span>${esc(t('name'))}</span><input id="dim-name" required value="${esc(d?.name||'')}"></label><label><span>${esc(t('maxScore'))}</span><input type="number" min="2" max="10" step="1" id="dim-max" required value="${d?.maximum||5}"></label><label><span>${esc(t('symbol'))}</span><select id="dim-symbol">${config.symbols.map(s=>`<option value="${s}" ${d?.symbol===s?'selected':''}>${symbols[s][0]} ${esc(t(s))}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" id="dim-gallery" ${d?.gallery?'checked':''}>${esc(t('galleryVisible'))}</label><div id="dimension-preview" aria-live="polite"></div><div class="actions">${btn(t('cancel'),'dim-cancel')}<button id="dim-save" class="btn primary" type="submit">${esc(t('save'))}</button></div></form>`);
 const form=$('#dimension-form'),maximumInput=$('#dim-max'),previewBox=$('#dimension-preview'),save=$('#dim-save'),errorBox=$('#dimension-error');
 const editorVersion=routeVersion;let preview=null,busy=false,needsPreview=false;
 const active=()=>form.isConnected&&dialog.open&&editorVersion===routeVersion;
 function resetPreview(){preview=null;previewBox.innerHTML='';save.textContent=t(d&&(needsPreview||Number(maximumInput.value)!==d.maximum)?'previewConversion':'save')}
 maximumInput.oninput=resetPreview;resetPreview();$('#dim-cancel').onclick=closeModal;
 form.onsubmit=async e=>{
  e.preventDefault();if(busy)return;
  const data={name:$('#dim-name').value,maximum:Number(maximumInput.value),symbol:$('#dim-symbol').value,gallery:$('#dim-gallery').checked};
  busy=true;save.disabled=true;errorBox.innerHTML='';
  try{
   if(d&&(needsPreview||data.maximum!==d.maximum)&&!preview){
    const result=await api('dimensions/'+d.id+'/preview','POST',{maximum:data.maximum});
    if(!active()||Number(maximumInput.value)!==data.maximum)return;
    preview=result;
    previewBox.innerHTML=`<h3>${esc(t('conversionTitle'))} · ${result.old_maximum} → ${result.maximum}</h3><p>${esc(t('conversionRule'))}</p><div class="conversion-table-wrap"><table class="conversion-table"><thead><tr><th>${esc(t('conversionBefore'))}</th><th>${esc(t('conversionAfter'))}</th><th>${esc(t('works'))}</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${r.old}/${result.old_maximum}</td><td>${r.new}/${result.maximum}</td><td>${r.count}</td></tr>`).join('')}</tbody></table></div><p>${esc(t('conversionSummary').replace('{rated}',result.rated).replace('{changed}',result.changed))}</p><div class="notice">${esc(t('conversionLoss'))}</div>`;
    save.textContent=t('confirmConversion');previewBox.scrollIntoView({block:'nearest'});return;
   }
   if(preview)data.conversion_signature=preview.signature;
   await api('dimensions'+(d?'/'+d.id:''),d?'PUT':'POST',data);
   markLibraryDirty();if(active()){closeModal();ratingPage()}
  }catch(e){if(active()){needsPreview=!!d;resetPreview();error(errorBox,e)}}
  finally{busy=false;if(active())save.disabled=false}
 }
}

let bookmarkItems=[],selectedBookmarks=new Set();
async function imports(){shell('imports',heading(t('importsTitle'),t('importsHint'))+`<label class="file-drop">${icon('upload')}<h3>${esc(t('upload'))}</h3><span>${esc(t('uploadHint'))}</span><input id="bookmark-file" type="file" accept=".html,.htm,text/html"></label><div id="import-error"></div><div id="bookmark-preview"></div><h2 class="results-line">${esc(t('jobs'))}</h2><div id="jobs" class="directory-list"></div>`);$('#bookmark-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>12*1024*1024)throw Error(t('uploadHint'));bookmarkItems=await api('bookmarks','POST',{html:await f.text()});selectedBookmarks=new Set(bookmarkItems.map((b,i)=>b.supported&&!b.duplicate?i:-1).filter(i=>i>=0));paintBookmarkPreview()}catch(e){error($('#import-error'),e)}};await loadJobs()}
function paintBookmarkPreview(){const folders=[...new Set(bookmarkItems.map(b=>b.folder))];$('#bookmark-preview').innerHTML=`<section class="panel stack"><div class="row between"><h3>${esc(t('preview'))} · ${bookmarkItems.length}</h3><span id="selected-count" class="muted small"></span></div><div class="row wrap">${btn(t('selectAll'),'select-all')}${btn(t('selectNone'),'select-none')}<select id="folder-filter" aria-label="${esc(t('folder'))}"><option value="*">${esc(t('allFolders'))}</option>${folders.map(f=>`<option value="${esc(f)}">${esc(f||'/')}</option>`).join('')}</select></div><div class="bookmark-list" id="bookmark-list"></div>${btn(t('startImport'),'start-job','primary','upload')}</section>`;const paint=()=>{const f=$('#folder-filter').value;$('#bookmark-list').innerHTML=bookmarkItems.map((b,i)=>({b,i})).filter(({b})=>f==='*'||b.folder===f).map(({b,i})=>`<label class="bookmark-row"><input type="checkbox" data-bookmark="${i}" ${selectedBookmarks.has(i)?'checked':''} ${!b.supported||b.duplicate?'disabled':''}><div class="info">${esc(b.label||b.url)}<small>${esc(b.folder)}<br>${esc(b.url)}</small></div><span class="status">${esc(t(b.duplicate?'duplicate':b.supported?'supported':'unsupported'))}</span></label>`).join('');$('#selected-count').textContent=`${selectedBookmarks.size} / ${bookmarkItems.length}`;$$('[data-bookmark]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.bookmark);el.checked?selectedBookmarks.add(i):selectedBookmarks.delete(i);$('#selected-count').textContent=`${selectedBookmarks.size} / ${bookmarkItems.length}`})};$('#folder-filter').onchange=paint;$('#select-all').onclick=()=>{const f=$('#folder-filter').value;bookmarkItems.forEach((b,i)=>{if(b.supported&&!b.duplicate&&(f==='*'||f===b.folder))selectedBookmarks.add(i)});paint()};$('#select-none').onclick=()=>{const f=$('#folder-filter').value;bookmarkItems.forEach((b,i)=>{if(f==='*'||f===b.folder)selectedBookmarks.delete(i)});paint()};$('#start-job').onclick=async()=>{if(!selectedBookmarks.size)return;try{const job=await api('jobs','POST',{items:[...selectedBookmarks].map(i=>bookmarkItems[i])});nav('/job/'+job.id)}catch(e){error($('#import-error'),e)}};paint()}
async function loadJobs(){const list=await api('jobs');if(!$('#jobs'))return;$('#jobs').innerHTML=list.map(j=>`<a class="directory-row" href="#/job/${j.id}"><div><div class="name">${new Date(j.created).toLocaleString(lang)}</div><div class="subtitle">${Object.values(j.counts).reduce((a,b)=>a+b,0)} ${esc(t('works'))} · ${j.counts.added||0} ${esc(t('added'))}</div></div><span class="status">${esc(t(j.status))}</span></a>`).join('')||`<p class="muted small">${esc(t('noJobs'))}</p>`;jobTimer=setTimeout(loadJobs,3000)}
async function jobPage(id){shell('imports',heading(t('jobResults'),t('jobHint'),`<a class="btn" href="#/imports">${icon('arrow')}${esc(t('imports'))}</a>`)+`<div id="job-summary"></div><div id="job-items" class="bookmark-list"></div>`);let displayedDuplicates=false;const poll=async()=>{clearTimeout(jobTimer);try{const j=await api('jobs/'+id);if(!$('#job-summary'))return;const total=j.items.length,done=j.items.filter(i=>!['pending','running'].includes(i.status)).length;$('#job-summary').innerHTML=`<div class="panel"><div class="row between"><h3>${esc(t(j.status))} · ${done}/${total}</h3><div class="row">${j.status==='running'?btn(t('cancelJob'),'cancel-job'):''}${btn(t('retryFailed'),'retry-job')}</div></div><div class="progress"><div style-width="${total?done/total*100:0}"></div></div><div class="row wrap">${Object.entries(j.counts).map(([s,n])=>`<span class="status ${s}">${esc(t(s))}: ${n}</span>`).join('')}</div></div>`;$('.progress>div').style.width=(total?done/total*100:0)+'%';$('#job-items').innerHTML=j.items.map(i=>`<div class="bookmark-row"><div class="info">${i.work_id?`<a href="#/work/${i.work_id}">${esc(i.title)}</a>`:esc(i.title||i.label||i.url)}<small>${esc(i.url)}${i.message?'<br>'+esc(localizeError(i.message,lang)):''}</small></div><span class="status ${i.status}">${esc(t(i.status))}</span></div>`).join('');$('#cancel-job')?.addEventListener('click',async()=>{await api('jobs/'+id+'/cancel','POST',{});poll()});$('#retry-job').onclick=async()=>{await api('jobs/'+id+'/retry','POST',{});displayedDuplicates=false;poll()};if(j.status==='complete'&&!displayedDuplicates){displayedDuplicates=true;const duplicates=j.items.filter(i=>i.status==='duplicate_title');if(duplicates.length&&!dialog.open){modal(`<h2>${esc(t('skipTitles'))}</h2><div class="stack">${duplicates.map(i=>`<p>${esc(i.title)}</p>`).join('')}</div><div class="actions">${btn(t('close'),'duplicates-close')}</div>`);$('#duplicates-close').onclick=closeModal}}if(j.status==='running')jobTimer=setTimeout(poll,2500)}catch(e){toast(e.message)}};await poll()}
function sourceTools(){return `<section class="panel stack"><h3>${esc(t('sourceTools'))}</h3><p>${esc(t('sourceToolsHint'))}</p><p class="muted small">${esc(t('sourceLookupHint'))}</p><label><span>${esc(t('folioAddress'))}</span><input id="folio-address" type="url" value="${esc(localStorage.getItem('folio-source-address')||location.origin)}"></label><p id="bookmark-warning" class="notice small" hidden>${esc(t('bookmarkLocalWarning'))}</p><div id="bookmark-error"></div><label><span>${esc(t('bookmarkCode'))}</span><textarea id="bookmark-code" readonly rows="4" spellcheck="false"></textarea></label><div>${btn(t('copyBookmark'),'copy-bookmark')}</div><p class="muted small">${esc(t('bookmarkHelp'))}</p><p class="muted small">${esc(t('desktopBookmarkHelp'))} <a id="folio-bookmark" draggable="true">Folio</a></p><form id="source-open-form" class="stack"><label><span>${esc(t('sourcePaste'))}</span><input id="source-url" type="url" required placeholder="https://hitomi.la/reader/123.html#7"></label><div><button type="submit" class="btn primary">${esc(t('openInFolio'))}</button></div></form></section>`}
function bindSourceTools(){
 const paint=()=>{try{const base=new URL($('#folio-address').value),code=bookmarklet(base.href);$('#bookmark-code').value=code;$('#folio-bookmark').href=code;$('#copy-bookmark').disabled=false;$('#bookmark-error').innerHTML='';$('#bookmark-warning').hidden=!['localhost','127.0.0.1','[::1]'].includes(base.hostname);localStorage.setItem('folio-source-address',base.origin)}catch(e){$('#bookmark-code').value='';$('#folio-bookmark').removeAttribute('href');$('#copy-bookmark').disabled=true;error($('#bookmark-error'),e)}};
 paint();$('#folio-address').oninput=paint;
 $('#folio-bookmark').onclick=e=>{e.preventDefault();toast(t('bookmarkHelp'))};
 $('#copy-bookmark').onclick=async()=>{const field=$('#bookmark-code');try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(field.value)}else{field.focus();field.select();if(!document.execCommand('copy'))throw Error('copy')}toast(t('bookmarkCopied'))}catch{field.focus();field.select();toast(t('copyManually'))}};
 $('#source-open-form').onsubmit=e=>{e.preventDefault();nav('/source?'+new URLSearchParams({url:$('#source-url').value.trim()}))};
}
async function openSource(version){
 const value=route().params.get('url')||'';
 shell('library',heading(t('sourceChecking'),t('sourceToolsHint')));
 const result=await api('source-check','POST',{url:value});if(version!==routeVersion)return;
 if(result.match==='gallery'){
 const choice=await new Promise(resolve=>{modal(`<h2>${esc(t('sourceRelatedTitle'))}</h2><p>${esc(t('sourceRelatedHint'))}</p><div class="stack source-related-list">${result.matches.map(w=>`<button type="button" class="btn source-related-item" data-source-work="${w.id}"><b>${esc(w.title)}</b><small>${esc(w.source_url)}</small></button>`).join('')}</div><div class="actions wrap">${btn(t('cancel'),'source-cancel')}${btn(t('sourceImportNew'),'source-import-new','primary')}</div>`);$$('[data-source-work]').forEach(b=>b.onclick=()=>{closeModal();resolve(b.dataset.sourceWork)});$('#source-cancel').onclick=()=>{closeModal();resolve(null)};$('#source-import-new').onclick=()=>{closeModal();resolve('new')};dialog.oncancel=()=>resolve(null)});
 if(version!==routeVersion)return;if(choice===null){nav('/library');return}if(choice!=='new'){nav('/work/'+choice);return}
 }else if(result.matches.length===1){nav('/work/'+result.matches[0].id);return}
 else if(result.matches.length){shell('library',heading(t('sourceMatches'),t('sourceMatchesHint'))+`<div class="directory-list">${result.matches.map(w=>`<a class="directory-row" href="#/work/${w.id}">${esc(w.title)}</a>`).join('')}</div>`);return}
 draft=blank();baseline=JSON.stringify(draft);draft.links=[{url:result.url,label:'',is_primary:true}];
 history.replaceState(null,'','#/new');previousHash=location.hash;
 await edit(null,true);if(version!==routeVersion)return;await interactiveImport(null,true);
}
function settings(){shell('settings',heading(t('settingsTitle'),t('settingsHint'))+`<div class="stack"><section class="panel stack"><h3>${esc(t('appearance'))}</h3><div class="row wrap">${btn(t('darkTheme'),'theme-dark',theme==='dark'?'primary':'')}${btn(t('lightTheme'),'theme-light',theme==='light'?'primary':'')}</div></section><section class="panel stack"><h3>${esc(t('localServer'))}</h3><p class="muted small">${esc(t('serverHint'))}</p><code>${esc(location.origin)}</code></section><section class="panel stack"><h3>${esc(t('backup'))}</h3><p class="muted small">${esc(t('backupHint'))}</p><div>${btn(t('backup'),'backup-now','','upload')}</div><div id="backup-result"></div></section><section class="panel stack"><h3>${esc(t('uiLanguage'))}</h3><div class="row">${btn(t('english'),'lang-en',lang==='en'?'primary':'')}${btn(t('japanese'),'lang-ja',lang==='ja'?'primary':'')}</div></section>${sourceTools()}</div>`);bindSourceTools();$('#theme-dark').onclick=()=>setTheme('dark');$('#theme-light').onclick=()=>setTheme('light');$('#lang-en').onclick=()=>switchLanguage('en');$('#lang-ja').onclick=()=>switchLanguage('ja');$('#backup-now').onclick=async()=>{try{const r=await api('backup','POST',{});$('#backup-result').textContent=t('backupDone')+': '+r.file}catch(e){error($('#backup-result'),e)}}}
let previousHash=location.hash||'#/library', restoring=false;
async function render(reuse=false){const version=++routeVersion;clearTimeout(jobTimer);try{await refreshConfig();if(version!==routeVersion)return;const {path}=route();if(path==='/library'){draft=null;await library()}else if(path.startsWith('/work/')){draft=null;await detail(path.split('/')[2])}else if(path==='/source'){draft=null;await openSource(version)}else if(path==='/new'||path.startsWith('/edit/'))await edit(path==='/new'?null:path.split('/')[2],reuse);else{draft=null;if(path==='/metadata')await metadata();else if(path==='/ratings')await ratingPage();else if(path==='/imports')await imports();else if(path.startsWith('/job/'))await jobPage(path.split('/')[2]);else if(path==='/settings')settings();else nav('/library')}if(path!=='/library')scrollTo(0,0)}catch(e){shell('library',`<div class="error">${esc(e.message)}</div>${btn(t('retry'),'retry-render')}`);$('#retry-render').onclick=()=>render(reuse)}}
window.addEventListener('hashchange',async()=>{if(restoring){restoring=false;return}if(draft&&JSON.stringify(draft)!==baseline){const target=location.hash;history.replaceState(null,'',previousHash);if(!await confirm(t('discardTitle'),t('discardText'),t('discard')))return;draft=null;history.replaceState(null,'',target)}previousHash=location.hash;render()});
window.addEventListener('beforeunload',e=>{if(draft&&JSON.stringify(draft)!==baseline){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&$('#query')){e.preventDefault();$('#query').focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap')){const el=$('#suggestions');if(el)el.innerHTML=''}if(e.target.closest('.card'))captureLibrary()});
render();

function setTheme(value){theme=value;localStorage.setItem('folio-theme',value);document.documentElement.dataset.theme=value;document.querySelector('meta[name="theme-color"]').content=value==='dark'?'#101010':'#f6f5f1';if(route().path==='/settings')settings()}
// A focused search lives at the top on phones. Other inputs hide the utility
// bar, avoiding overlap even on browsers that resize the layout viewport.
function updateUtilityFocus(){
 const active=document.activeElement,root=document.documentElement;
 const searching=active?.closest?.('#bottom-search-form')||(root.dataset.utilityFocus==='search'&&active?.closest?.('.utility-bar'));
 root.dataset.utilityFocus=searching?'search':active?.matches?.('input,textarea,select,[contenteditable="true"]')?'editing':'idle';
 const viewport=window.visualViewport;
 root.style.setProperty('--visual-top',(viewport?.offsetTop||0)+'px');
 root.style.setProperty('--visual-height',(viewport?.height||window.innerHeight)+'px');
}
document.addEventListener('focusin',updateUtilityFocus);
document.addEventListener('focusout',()=>requestAnimationFrame(updateUtilityFocus));
window.visualViewport?.addEventListener('resize',updateUtilityFocus);
window.visualViewport?.addEventListener('scroll',updateUtilityFocus);
window.addEventListener('resize',updateUtilityFocus);
updateUtilityFocus();
